ALTER TABLE public.students ADD COLUMN program text NOT NULL DEFAULT 'CNA', ADD COLUMN is_over_16 boolean, ADD COLUMN is_cna boolean, ADD COLUMN wants_cna_next boolean, ADD COLUMN physically_able boolean, ADD COLUMN preferred_schedule text;
ALTER TABLE public.students ADD CONSTRAINT students_email_program_key UNIQUE (email, program);
CREATE OR REPLACE FUNCTION public.validate_applicant_program() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.program NOT IN ('CNA','HHA') THEN RAISE EXCEPTION 'Invalid program'; END IF; IF NEW.program = 'HHA' AND (NEW.selected_cohort_date IS NOT NULL OR NEW.orientation_date IS NOT NULL OR NEW.cohort_id IS NOT NULL OR NEW.preferred_schedule NOT IN ('Daytime','Weekend','Either')) THEN RAISE EXCEPTION 'HHA is a priority list without cohort or orientation dates'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validate_applicant_program BEFORE INSERT OR UPDATE ON public.students FOR EACH ROW EXECUTE FUNCTION public.validate_applicant_program();